      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.ImageUrlDetail",
  "description": "Detail level for image processing.",
  "oneOf": [
    {
      "description": "Let the model decide the detail level.",
      "type": "string",
      "const": "auto"
    },
    {
      "description": "Low detail mode (faster, less tokens).",
      "type": "string",
      "const": "low"
    },
    {
      "description": "High detail mode (more accurate, more tokens).",
      "type": "string",
      "const": "high"
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.File",
  "description": "A file attachment for multimodal input.",
  "type": "object",
  "properties": {
    "file_data": {
      "description": "Base64-encoded file data.",
      "type": [
        "string",
        "null"
      ]
    },
    "file_id": {
      "description": "The ID of a previously uploaded file.",
      "type": [
        "string",
        "null"
      ]
    },
    "filename": {
      "description": "The filename for display purposes.",
      "type": [
        "string",
        "null"
      ]
    },
    "file_url": {
      "description": "A URL to fetch the file from.",
      "type": [
        "string",
        "null"
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.alpha_scalar.PlaceholderScalarFunctionTaskExpression",
  "type": "object",
  "properties": {
    "depth": {
      "type": "integer",
      "format": "uint64",
      "minimum": 0
    },
    "min_branch_width": {
      "type": "integer",
      "format": "uint64",
      "minimum": 0
    },
    "max_branch_width": {
      "type": "integer",
      "format": "uint64",
      "minimum": 0
    },
    "min_leaf_width": {
      "type": "integer",
      "format": "uint64",
      "minimum": 0
    },
    "max_leaf_width": {
      "type": "integer",
      "format": "uint64",
      "minimum": 0
    },
    "name": {
      "type": "string"
    },
    "spec": {
      "type": "string"
    },
    "input_schema": {
      "$ref": "functions.expression.ObjectInputSchema"
    },
    "skip": {
      "anyOf": [
        {
          "$ref": "functions.expression.Expression"
        },
        {
          "type": "null"
        }
      ]
    },
    "input": {
      "$ref": "functions.expression.Expression"
    }
  },
  "required": [
    "depth",
    "min_branch_width",
    "max_branch_width",
    "min_leaf_width",
    "max_leaf_width",
    "name",
    "spec",
    "input_schema",
    "input"
  ]
}

